/* 作品阅读、连载与收益交互。本机模拟，发布快照与原工程隔离。 */
(()=>{
 'use strict';
 const S=Site,C=Cimora,E=S.esc,H=()=>StudioLibrary,copy=value=>JSON.parse(JSON.stringify(value));
 const labels={story:'故事',comic:'漫画',video:'视频',tool:'图像与声音'};
 const image=src=>StudioLibraryModel.imageOf(src,true),page=i=>'comic-studio/examples/romance-two/josei/deliverables/page-0'+i+'.png';
 const base={author:'Cimora 官方示例',demo:true,visibility:'square',supportEnabled:true,currency:'points',createdAt:'2026-11-12T00:00:00Z'};
 const examples=[
  {...base,id:'rain-public',title:'离城之前',kind:'comic',cover:page(1),genre:'都市情感',status:'连载中',desc:'离开城市前的最后一顿宵夜，一条好友申请让三年的沉默重新有了声音。',chapters:[{id:'rain-first',title:'第1集 · 未读的好友申请',price:0,content:[{kind:'image',src:page(1),title:'第1页'},{kind:'image',src:page(2),title:'第2页'}]}],notice:'阅读演示 · 本集展示两页已有成稿，后续尚未发布。'},
  {...base,id:'sky-public',title:'星海邮局',kind:'story',cover:'assets/cimora-cover.webp',genre:'幻想治愈',status:'连载中',desc:'最后一封无法投递的信，收件人写着邮差自己的名字。',chapters:[
   {id:'sky-first',title:'第1集 · 没有地址的信',price:0,content:[{kind:'text',title:'第1集 · 没有地址的信',text:'夜班结束前，邮差小满在退信柜里发现一封没有邮戳的信。信封上写着她的名字，地址却是早已熄灯的旧灯塔。\n\n她搭上最后一班邮船。船夫没有收钱，只问她：“你是去送信，还是去收信？”\n\n灯塔门口，一只白猫踩住了她的鞋带。小满蹲下解开鞋带时，看见石阶上刻着一行小字：如果你终于来到这里，请别急着拆开。\n\n信封里忽然传出钟声。远处的邮船已经开始返航。'}]},
   {id:'sky-second',title:'第2集 · 灯塔里的钟声',price:20,currency:'points',content:[{kind:'text',title:'第2集 · 灯塔里的钟声',text:'钟声停在第十二下。\n\n小满推开灯塔的门，墙上挂着一排没有指针的钟。柜台后，一位老妇人正把空白信纸折成船。\n\n“你来得比上一次早。”老妇人说。\n\n小满握紧信封：“我们见过？”\n\n老妇人没有回答。她把一只纸船放进窗边的水盆，船底慢慢浮出一行熟悉的笔迹。\n\n那是小满小时候写给母亲的话。\n\n楼上传来脚步声，白猫抬起头，像在等一个终于归来的人。'}]}
  ],notice:'原创短篇示例 · 第1集免费，第2集用于演示付费阅读；没有真实扣款。'},
  {...base,id:'book-public',title:'我的第一个 OC',kind:'tool',cover:'assets/pngtuber/idle.png',genre:'角色创作',status:'单篇作品',desc:'银紫色短发、星星发饰，喜欢把今天的小事画进日记。',content:[{kind:'image',src:'assets/pngtuber/idle.png',title:'角色主形象'}],notice:'角色图展示示例，不包含可运行模型或素材下载。'},
  {...base,id:'light-public',title:'归途的灯',kind:'video',cover:'assets/short-film/shot-1.jpg',genre:'温暖日常',status:'效果占位',supportEnabled:false,desc:'女孩为男孩系上围巾，两人提着纸灯走向亮灯的小屋。',content:[{kind:'placeholder',title:'视频效果占位',text:'正式作品在这里播放整集视频，包含对白和背景音乐。目前只有封面示意，尚无可播放的视频或声音。'}],notice:'效果占位 · 不提供付费解锁或支持。'}
 ];
 let records=[],favorites=[],reader={following:[],unlocks:[],orders:[]},loaded=false,loading=false,failure='',databasePromise,refreshPromise;
 let filter={type:'all',tab:'featured',genre:'all',query:''},draft=null,busy=false;
 const urls=new Map(),money=(points,currency='points')=>currency==='points'?Number(points).toLocaleString('zh-CN')+' 积分':'¥'+(points/100).toFixed(2)+'（历史）';
 const button=(text,action,id='',primary=false)=>`<button type="button" class="cm-button ${primary?'primary':'ghost'}" data-cg="${action}" data-id="${E(id)}">${text}</button>`;
 const link=(text,url,cls='ghost')=>C.link(text,url,'cm-button '+cls);
 const safe=src=>typeof src==='string'&&(/^(data:(image|audio|video)\/|blob:|https?:\/\/)/i.test(src)||/^(assets|comic-studio)\/[\w./-]+$/.test(src))?src:'';
 function mediaURL(item){if(item.blob instanceof Blob){if(!urls.has(item.blob))urls.set(item.blob,URL.createObjectURL(item.blob));return urls.get(item.blob);}return safe(item.src);}
 function database(){if(!databasePromise)databasePromise=new Promise((resolve,reject)=>{const r=indexedDB.open('cimora-community-v1',1);r.onupgradeneeded=()=>{r.result.createObjectStore('works',{keyPath:'id'});r.result.createObjectStore('preferences');};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('作品展示库无法打开，原工程保留。'));r.onblocked=()=>reject(Error('作品展示库被旧窗口占用，请关闭旧窗口再试。'));}).catch(e=>{databasePromise=null;throw e;});return databasePromise;}
 async function read(store,key){const db=await database();return new Promise((resolve,reject)=>{const r=key===undefined?db.transaction(store).objectStore(store).getAll():db.transaction(store).objectStore(store).get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
 async function write(store,value,key){const db=await database();await new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');key===undefined?tx.objectStore(store).put(value):tx.objectStore(store).put(value,key);tx.oncomplete=resolve;tx.onabort=()=>reject(Error('本机空间不足，本次未保存；已有作品与原工程保留。'));tx.onerror=()=>{};});}
 const onCommunity=()=>['community','creator'].includes(S.context?.parts[1]);
 function refresh(){if(refreshPromise)return refreshPromise;refreshPromise=(async()=>{loading=true;try{records=await read('works');favorites=await read('preferences','favorites')||[];reader={following:[],unlocks:[],orders:[],...await read('preferences','reader-v1')};loaded=true;failure='';}catch(e){failure=e.message;}finally{loading=false;refreshPromise=null;if(onCommunity())S.render();}})();return refreshPromise;}
 function legacy(){return (C.M.db.publications||[]).filter(w=>!records.some(r=>r.id===w.id)).map(w=>({...w,kind:w.type==='motion'?'video':'comic',visibility:'private',legacy:true,content:(w.snapshot?.boards||[]).map(b=>({kind:'image',src:Art.url(b.art),title:b.title,text:b.dialogue})),notice:'历史本机作品快照，仅自己可见。'}));}
 const all=()=>[...records.map(w=>({...w,author:window.StudioAccount?StudioAccount.author({...w,authorId:'local-creator'}):w.author})),...legacy(),...examples],find=id=>all().find(w=>w.id===id);
 const owned=w=>!!w&&!w.demo&&!w.legacy&&records.some(r=>r.id===w.id);
 const chapters=w=>w.chapters?.length?w.chapters:[{id:w.id+'-chapter',title:w.kind==='tool'?'作品展示':'第1集',price:0,content:w.content||[]}];
 const currentChapter=w=>chapters(w).find(ch=>ch.id===S.context.params.get('chapter'))||chapters(w)[0];
 const cover=w=>safe(w.cover)||mediaURL(chapters(w)[0].content?.find(i=>i.kind==='image')||{})||'assets/cimora-cover.webp';
 const badge=w=>w.legacy?'历史快照':w.demo?'官方示例':w.visibility==='private'?'仅自己可见':'本机发布';
 const chapterURL=(w,ch)=>'/app/community/'+encodeURIComponent(w.id)+'?chapter='+encodeURIComponent(ch.id);
 const unlocked=(w,ch)=>!ch.price||owned(w)||reader.unlocks.includes(w.id+':'+ch.id)||PointsWallet.entitled(w.id,ch.id);
 const commerceNote='<p class="cg-disclaimer">本机交互演示 · 新交易统一使用积分，扣除本机演示余额；无真实付款、结算或提现。</p>';
 function card(w){const paid=chapters(w).some(ch=>ch.price>0);return `<a class="cg-card" href="#/app/community/${encodeURIComponent(w.id)}" aria-label="${E(w.title+' · '+labels[w.kind])}"><div class="cg-cover"><img loading="lazy" src="${E(cover(w))}" alt="${E(w.title)}"><span>${labels[w.kind]}</span>${w.status==='效果占位'?'<b>视频占位</b>':''}</div><section><small>${E(w.genre||'自由创作')} · ${badge(w)}</small><h2>${E(w.title)}</h2><p>${E(w.desc||'一份新的创作')}</p><div class="cg-work-meta">${E(w.status||'单篇作品')}${w.kind!=='tool'?' · '+chapters(w).length+'集':''} · ${paid?'含付费章节':'免费阅读'}</div><footer><span>${E(w.author)}</span><span>${reader.following.includes(w.id)?'已追更':'打开作品 →'}</span></footer></section></a>`;}
 function listView(){
  const visible=all().filter(w=>filter.tab==='mine'?!w.demo:filter.tab==='favorites'?favorites.includes(w.id):w.visibility==='square');
  let rows=visible.filter(w=>(filter.tab!=='following'||reader.following.includes(w.id))&&(filter.type==='all'||w.kind===filter.type)&&(filter.genre==='all'||w.genre===filter.genre)&&(!filter.query||[w.title,w.desc,w.author,w.genre].join(' ').toLowerCase().includes(filter.query.toLowerCase())));
  if(['latest','mine'].includes(filter.tab))rows=rows.slice().sort((a,b)=>(b.updatedAt||b.createdAt||'').localeCompare(a.updatedAt||a.createdAt||''));
  const genres=[...new Set(all().map(w=>w.genre).filter(Boolean))];
  return `<div class="cg-page"><header class="cg-heading"><div><span class="cm-kicker">STORIES WORTH FOLLOWING</span><h1>作品广场</h1><p>遇见喜欢的故事，追上每一次更新，让好作品被看见。</p></div><div class="cg-actions">${link('创作者中心','/app/creator?tab=works')}${button('发布我的作品','publish','',true)}</div></header><div class="cg-disclaimer">本机演示 · 发布、收藏、追更与付费体验仅保存在当前浏览器。</div>${filter.tab==='featured'&&!filter.query&&filter.type==='all'&&filter.genre==='all'?`<section class="cg-feature"><img src="${page(1)}" alt="离城之前漫画成稿"><div><small>精选漫画 · 都市情感 · 连载中</small><h2>离城之前</h2><p>一句“你明天几点走”，打断了三年的沉默。</p>${link('开始阅读 ↗','/app/community/rain-public','primary')}</div></section>`:''}<nav class="cg-tabs" aria-label="作品列表">${[['featured','精选'],['latest','最新更新'],['following','我的追更'],['favorites','我的收藏'],['mine','我的发布']].map(([id,t])=>`<button data-cg="tab" data-id="${id}" aria-pressed="${filter.tab===id}">${t}</button>`).join('')}</nav><section class="cg-filters"><div class="cg-types">${[['all','全部'],...Object.entries(labels)].map(([id,t])=>`<button data-cg="type" data-id="${id}" aria-pressed="${filter.type===id}">${t}</button>`).join('')}</div><div class="cg-search-row"><label>题材<select data-cg-field="genre" aria-label="筛选题材"><option value="all">全部题材</option>${genres.map(t=>`<option ${filter.genre===t?'selected':''}>${E(t)}</option>`).join('')}</select></label><label class="cg-search">搜索<input data-cg-field="query" aria-label="搜索作品" placeholder="作品、作者或题材" value="${E(filter.query)}"></label>${button('筛选','search')}</div></section>${failure?`<div class="cm-notice warning" role="alert">${E(failure)}${button('重试读取','reload')}</div>`:''}<p class="cg-count">${rows.length} 份作品${!loaded?' · 正在读取本机发布…':''}</p><div class="cg-grid">${rows.map(card).join('')||`<div class="cg-empty"><h2>${filter.tab==='following'?'还没有追更的作品':'暂时没有符合条件的作品'}</h2><p>从喜欢的故事开始，收藏作品或加入追更。</p>${button('浏览全部作品','reset')}</div>`}</div><p class="cg-foot">关注作品本身，支持持续创作。作者保留原工程、提示词与创作资产。</p></div>`;
 }
 function renderContent(content){return (content||[]).map(i=>i.kind==='text'?`<article class="cg-text"><h2>${E(i.title||'正文')}</h2><p>${E(i.text)}</p></article>`:i.kind==='image'?`<figure><img src="${E(mediaURL(i))}" alt="${E(i.title||'作品图片')}"><figcaption>${E(i.title||'')}${i.text?' · '+E(i.text):''}</figcaption></figure>`:i.kind==='video'?`<figure><video controls preload="metadata" src="${E(mediaURL(i))}"></video><figcaption>${E(i.title||'视频作品')}</figcaption></figure>`:i.kind==='audio'?`<article class="cg-audio"><h2>${E(i.title||'声音作品')}</h2><audio controls preload="metadata" src="${E(mediaURL(i))}"></audio></article>`:`<article class="cg-empty"><h2>${E(i.title||'效果占位')}</h2><p>${E(i.text||'尚无可播放媒体。')}</p></article>`).join('');}
 function detail(w){
  const ch=currentChapter(w),items=chapters(w),index=items.indexOf(ch),canRead=unlocked(w,ch),follows=reader.following.includes(w.id),supports=[...reader.orders,...PointsWallet.orders()].filter(o=>o.workId===w.id&&(o.type||o.kind)==='support');
  const paywall=`<section class="cg-paywall"><span>继续阅读</span><h2>${E(ch.title)}</h2><p>本集为付费内容，解锁后可在当前浏览器反复阅读。</p>${button('解锁本集 · '+money(ch.price,ch.currency||w.currency||'legacy'),'unlock',w.id,true)}${commerceNote}<small>解锁仅获得阅读权限，不包含素材、工程或再创作授权。</small></section>`;
  return `<div class="cg-page"><div class="cg-back">${link('回到作品广场','/app/community')}${button('我的支持记录','orders')}</div><header class="cg-heading"><div><small>${labels[w.kind]} · ${E(w.genre||'自由创作')} · ${badge(w)}</small><h1>${E(w.title)}</h1><p>${E(w.status||'单篇作品')} · ${E(w.author)}</p></div>${button(favorites.includes(w.id)?'已收藏':'收藏作品','favorite',w.id)}</header><div class="cg-detail"><main><p>${E(w.desc||'')}</p>${w.notice?`<p class="cm-notice">${E(w.notice)}</p>`:''}${owned(w)?'<p class="cg-disclaimer">作者预览 · 可查看自己发布的所有章节。</p>':''}<div class="cg-reader">${canRead?renderContent(ch.content):paywall}</div><nav class="cg-reading-nav" aria-label="章节导航">${index>0?link('← 上一集',chapterURL(w,items[index-1])):''}${index<items.length-1?link('下一集 →',chapterURL(w,items[index+1]),'primary'):''}</nav></main><aside><section class="cm-panel cg-author"><span class="cm-kicker">THE CREATOR</span>${owned(w)&&window.StudioAccount?StudioAccount.avatar():''}<h2>${E(w.author)}</h2><p>${E(owned(w)&&window.StudioAccount?StudioAccount.profile().bio||'喜欢这份作品，就让作者知道。':'喜欢这份作品，就让作者知道。' )}</p>${owned(w)?link('创作者中心','/app/creator?tab=works')+link('查看作者主页','/app/creator/profile'):button(follows?'已追更':'追更作品','follow',w.id,true)}${!owned(w)&&w.supportEnabled!==false&&!w.legacy?button('支持作者','support',w.id):''}${supports.length?'<small>你已支持本作品 '+supports.length+' 次，谢谢你的鼓励。</small>':''}</section><section class="cm-panel cg-directory"><h3>${w.kind==='tool'?'作品内容':'章节目录'} <small>${items.length}${w.kind==='tool'?'份':'集'}</small></h3>${items.map(item=>`<button type="button" data-cg="chapter" data-id="${E(w.id)}" data-chapter="${E(item.id)}" aria-current="${item.id===ch.id?'true':'false'}"><span>${E(item.title)}</span><small>${item.price?(unlocked(w,item)?owned(w)?'作者预览':'已解锁':money(item.price,item.currency||w.currency||'legacy')):'免费'}</small></button>`).join('')}</section>${owned(w)?`<section class="cm-panel"><h3>作品管理</h3>${button('修改展示设置','settings',w.id)}${w.sourceURL?link('返回来源继续编辑',w.sourceURL):''}</section>`:''}</aside></div></div>`;
 }
 function openTransaction(w,type){
  if(!w||owned(w)||w.visibility!=='square'||w.status==='效果占位'||w.legacy)throw Error('当前作品不能进行这项操作。');
  const ch=currentChapter(w);if(type==='unlock'&&unlocked(w,ch))throw Error('本集已经可以阅读。');if(type==='unlock'&&(ch.currency||w.currency)!=='points')throw Error('本集为旧人民币标价，暂不开放新的积分交易。');if(type==='support'&&w.supportEnabled===false)throw Error('作者暂未开启支持。');
  draft={orderId:crypto.randomUUID(),transaction:type,workId:w.id,chapterId:ch.id,amount:type==='unlock'?ch.price:50};
  S.modal(type==='unlock'?'解锁本集':'支持作者',`<div class="cg-form"><h3>${E(w.title)}</h3><p>${type==='unlock'?E(ch.title)+' · '+money(ch.price,ch.currency||w.currency||'legacy'):'用一份支持，鼓励作者继续创作。支持不会自动解锁付费章节。'}</p>${type==='support'?'<label>支持金额<select data-cg-publish="amount"><option value="50">50 积分</option><option value="100">100 积分</option><option value="200">200 积分</option></select></label>':''}${commerceNote}<p>确认后扣除站内积分，保存购买权益；当前余额 ${PointsWallet.balance()} 积分。支持不会自动解锁章节。</p><p class="cg-error" role="alert" id="cg-publish-error"></p></div>`,button(type==='unlock'?'确认模拟解锁':'确认模拟支持','transact','',true));
 }
 async function transact(){
  const w=find(draft.workId),ch=w&&chapters(w).find(i=>i.id===draft.chapterId);if(!w||!ch||owned(w)||w.visibility!=='square')throw Error('作品状态已变化，请重新打开。');
  const type=draft.transaction;if(type==='unlock'&&unlocked(w,ch)){S.close();return;}
  const amount=type==='unlock'?ch.price:Number(draft.amount);if(!['support','unlock'].includes(type)||type==='unlock'&&(ch.currency||w.currency)!=='points'||type==='support'&&(w.supportEnabled===false||![50,100,200].includes(amount))||!Number.isSafeInteger(amount)||amount<=0)throw Error('积分金额无效，请重新选择。');
  const order={id:draft.orderId,kind:type,workId:w.id,title:w.title,author:w.author,chapterId:ch.id,chapterTitle:ch.title,amount,at:new Date().toISOString(),simulated:true};
  await PointsWallet.change(state=>{if(type==='unlock'&&state.orders.some(o=>o.kind==='unlock'&&o.workId===w.id&&o.chapterId===ch.id&&o.status==='paid'))return;PointsModel.pay(state,order);});S.close();S.render();S.toast(type==='unlock'?'本集已解锁 · 演示积分已扣除':'支持已记录 · 演示积分已扣除');
 }
 function orders(){S.route('/app/settings?tab=purchases&type=support');}
 function earnings(){return '<div class="sa-page">'+StudioAccount.centerHeader('income')+PointsWallet.income()+'</div>';}
 function sourceItems(kind){const index=H().load();return kind==='tool'?index.assets.filter(a=>a.tool&&a.key.startsWith('tool:')&&a.state==='active'):index.projects.filter(p=>p.kind===kind&&p.state==='active');}
 const selectedSource=()=>sourceItems(draft.kind).find(p=>p.key===draft.key);
 const sourceEpisodes=p=>draft.kind==='tool'?[]:p?.episodes||[];
 function publish(sourceKey){draft={kind:'story',key:'',episode:'',seriesId:'',title:'',chapterTitle:'',desc:'',genre:'自由创作',visibility:'private',access:'free',price:'2',supportEnabled:true,status:'连载中'};resetSource();if(sourceKey){const p=H().findProject(sourceKey);if(p?.state==='active'){draft.kind=p.kind;draft.key=p.key;resetEpisode();}}drawPublish();}
 function resetSource(){const p=sourceItems(draft.kind)[0];draft.key=p?.key||'';resetEpisode();}
 function resetEpisode(){const p=selectedSource(),ep=sourceEpisodes(p)[0];draft.episode=ep?.id||'';draft.chapterTitle=ep?.title||'作品展示';draft.title=p?.title||p?.name||'';draft.seriesId='';draft.access='free';draft.demoVideo=false;if(draft.kind==='video')draft.supportEnabled=false;draft.status=draft.kind==='tool'?'单篇作品':'连载中';}
 function monetizationFields(){if(draft.kind==='video')return `<label><input type="checkbox" data-cg-publish="demoVideo" ${draft.demoVideo?'checked':''}>发布静态演示成品（无可播放视频、不可收费）</label>`;return `${['story','comic'].includes(draft.kind)?`<label>阅读方式<select data-cg-publish="access"><option value="free" ${draft.access==='free'?'selected':''}>本集免费</option><option value="paid" ${draft.access==='paid'?'selected':''}>本集付费（模拟）</option></select></label>${draft.access==='paid'?`<label>本集价格（积分）<input type="number" min="1" max="9999" step="1" data-cg-publish="price" value="${E(draft.price)}"></label>`:''}`:''}<label class="cg-check"><input type="checkbox" data-cg-publish="supportEnabled" ${draft.supportEnabled?'checked':''}>开启读者支持</label>${commerceNote}`;}
 function drawPublish(){
  const sources=sourceItems(draft.kind),p=selectedSource(),eps=sourceEpisodes(p),series=records.filter(w=>w.kind===draft.kind&&w.sourceKey===draft.key),existing=records.find(w=>w.id===draft.seriesId);
  S.modal('准备发布作品',`<div class="cg-form"><p>发布完成的作品，让读者阅读、追更并支持你。原工程、提示词和创作资产不会公开。</p><label>作品来源<select data-cg-publish="kind">${Object.entries(labels).map(([k,t])=>`<option value="${k}" ${draft.kind===k?'selected':''}>${k==='tool'?'创作工具':t}</option>`).join('')}</select></label><label>来源作品<select data-cg-publish="key">${sources.map(item=>`<option value="${E(item.key)}" ${draft.key===item.key?'selected':''}>${E(item.title||item.name)}</option>`).join('')||'<option value="">暂无已保存成果</option>'}</select></label>${eps.length?`<label>发布范围<select data-cg-publish="episode">${eps.map(ep=>`<option value="${E(ep.id)}" ${draft.episode===ep.id?'selected':''}>${E(ep.title)}</option>`).join('')}</select></label>`:''}${draft.kind!=='tool'&&series.length?`<label>发布到<select data-cg-publish="seriesId"><option value="">新建作品</option>${series.map(w=>`<option value="${E(w.id)}" ${draft.seriesId===w.id?'selected':''}>${E(w.title)} · 追加一集</option>`).join('')}</select></label>`:''}${!existing?`<label>作品标题<input data-cg-publish="title" value="${E(draft.title)}" maxlength="60"></label><label>作品简介<textarea data-cg-publish="desc" rows="2" maxlength="400">${E(draft.desc)}</textarea></label><label>题材<input data-cg-publish="genre" value="${E(draft.genre)}" maxlength="30"></label>`:`<p>向《${E(existing.title)}》追加一集，保留已发布章节。</p>`}${eps.length?`<label>本集标题<input data-cg-publish="chapterTitle" value="${E(draft.chapterTitle)}" maxlength="60"></label>`:''}<label>更新状态<select data-cg-publish="status">${(draft.kind==='tool'?['单篇作品']:['连载中','已完结']).map(status=>`<option ${draft.status===status?'selected':''}>${status}</option>`).join('')}</select></label><label>展示范围<select data-cg-publish="visibility"><option value="private" ${draft.visibility==='private'?'selected':''}>仅自己可见</option><option value="square" ${draft.visibility==='square'?'selected':''}>作品广场（本机演示）</option></select></label>${monetizationFields()}<p class="cm-notice">${draft.kind==='video'?'先在整集制作保存演示成品，再勾选发布演示；真实成片仍需实际视频文件。':'只发布所选集的完整正文或已采用的漫画成稿；工具成果独立发布，无需关联项目。'}</p>${p?link('先查看来源',p.url||'/app/tool-results'):''}<p class="cg-error" role="alert" id="cg-publish-error"></p></div>`,button('保存作品快照','commit','',true),true);
 }
 async function frozen(src){src=safe(src);if(!src)throw Error('媒体来源无效。');const r=await fetch(src);if(!r.ok)throw Error('媒体读取失败，请返回来源检查。');const blob=await r.blob();if(!blob.size)throw Error('媒体文件为空。');return blob;}
 async function prepare(revisionId){
  const p=selectedSource();if(!p)throw Error('先选择一份已保存的成果。');const existing=records.find(w=>w.id===draft.seriesId),title=(existing?.title||draft.title).trim();if(!title)throw Error('请填写作品标题。');
  const raw=p.raw,ep=sourceEpisodes(p).find(e=>e.id===draft.episode),content=[];
  if(existing&&(existing.sourceKey!==draft.key||existing.kind!==draft.kind))throw Error('作品来源不一致，请重新选择。');
  if(existing&&chapters(existing).some(ch=>ch.sourceEpisode===ep?.id)&&!revisionId)throw Error('本集已经发布，请选择另一集；已发布成稿保留。');
  let price=0;if(draft.access==='paid'&&['story','comic'].includes(draft.kind)){const value=Number(draft.price);if(!Number.isSafeInteger(value)||value<1||value>9999)throw Error('本集价格需要为 1–9999 的整数积分。');price=value;}
  if(draft.kind==='story'){
   if(!ep)throw Error('所选故事尚无分集，请先完成正文。');const text=ScriptStudio.bodyText(raw,ep.id);if(!text.trim())throw Error('所选集尚无正文，请先回故事工作台完成。');content.push({kind:'text',title:draft.chapterTitle||ep.title,text});
  }else if(draft.kind==='comic'){
   if(!ep)throw Error('所选漫画尚无分集。');const pages=ExportCenterModel.comicPages(raw,p.episodes,[ep.id]);for(const pg of pages)content.push({kind:'image',title:pg.name,blob:await frozen(image(pg.image))});
  }else if(draft.kind==='video'){const delivery=(p.entries||[]).flatMap(entry=>entry.workspace.demoDeliveries||[]).find(d=>d.episodeId===ep?.id);if(!draft.demoVideo||!delivery)throw Error('所选视频没有可发布的真实整集文件。可先在整集制作保存演示成品，勾选后发布静态演示。');content.push({kind:'placeholder',title:'视频演示成品 · 非可播放视频',text:delivery.notice});for(const [i,clip]of delivery.clips.entries())if(clip.image)content.push({kind:'image',title:'第'+(i+1)+'镜 · 静态示意',blob:await frozen(image(clip.image))});draft.supportEnabled=false;draft.status='效果占位';}
  else{
   const files=await ToolStudio.exportFiles(copy(raw));
   for(const f of files){const ext=f.name.split('.').pop().toLowerCase(),kind=/^(png|jpg|jpeg|webp|gif)$/.test(ext)?'image':/^(mp4|webm)$/.test(ext)?'video':/^(wav|mp3|ogg)$/.test(ext)?'audio':null;if(!kind)continue;const blob=f.data instanceof Blob?f.data:new Blob([f.data]);if(blob.size)content.push({kind,title:f.name,blob});}
   if(!content.length)throw Error('这份成果尚无可展示的图像、声音或视频。请先在工具里生成并保存成果。');
  }
  const ch={id:'chapter-'+crypto.randomUUID(),title:draft.chapterTitle||ep?.title||'作品展示',price,currency:'points',content,sourceEpisode:ep?.id,createdAt:new Date().toISOString()};
  if(revisionId){const old=chapters(existing).find(ch=>ch.id===revisionId);if(!old||old.sourceEpisode!==ep?.id)throw Error('所选章节来源不一致。');const {revisions,...prior}=old;return {...existing,chapters:chapters(existing).map(item=>item.id===old.id?{...old,content,title:ch.title,updatedAt:ch.createdAt,revisions:[prior,...(revisions||[])]}:item),updatedAt:ch.createdAt};}
  if(existing)return {...existing,chapters:[...chapters(existing),ch],visibility:draft.visibility,status:draft.status,supportEnabled:!!draft.supportEnabled,updatedAt:ch.createdAt,permissions:{},shared:{}};
  return {id:'community-'+crypto.randomUUID(),title,kind:draft.kind,author:window.StudioAccount?StudioAccount.profile().name:'我的工作室',authorId:'local-creator',desc:draft.desc.trim(),genre:draft.genre.trim()||'自由创作',visibility:draft.visibility,status:draft.status,supportEnabled:!!draft.supportEnabled,permissions:{},shared:{},chapters:[ch],sourceURL:p.url||'/app/tool-results',sourceKey:p.key,createdAt:ch.createdAt,demoOnly:draft.kind==='video',notice:draft.kind==='video'?'静态演示成品，未输出真实整集视频，不提供付费与支持。':raw.notice||raw.exampleCase?'包含示例或预置素材，未调用新的生成模型。':'发布时保存的独立成稿快照。'};
 }
 async function commit(){const w=await prepare();await write('works',w);records=[w,...records.filter(r=>r.id!==w.id)];loaded=true;S.close();S.route(chapterURL(w,chapters(w).at(-1)));S.toast('作品已保存 · '+(w.visibility==='private'?'仅自己可见':'本机广场展示'));}
 let revisionPreview=null;
 async function previewRevision(id,chapterId){
  await refresh();const w=records.find(item=>item.id===id),ch=w&&chapters(w).find(item=>item.id===chapterId);if(!owned(w)||!ch)throw Error('只能更新自己的已发布章节。');
  draft={kind:w.kind,key:w.sourceKey,episode:ch.sourceEpisode,seriesId:w.id,title:w.title,chapterTitle:ch.title,visibility:w.visibility,status:w.status,supportEnabled:w.supportEnabled,access:'free'};
  const next=await prepare(ch.id),updated=next.chapters.find(item=>item.id===ch.id);
  revisionPreview={work:next,chapterId:ch.id,based:JSON.stringify(ch)};
  const display=items=>items.map(item=>item.kind==='text'?`<pre class="cg-text">${E(item.text)}</pre>`:item.kind==='image'?`<img style="max-width:100%" src="${E(mediaURL(item))}" alt="${E(item.title)}">`:`<p>${E(item.title||'作品内容')}</p>`).join('');
  S.modal('更新本集成稿',`<div class="cg-form"><p>只更新本集成稿；章节地址、价格、读者解锁和其他集保持原状。旧成稿存入修订记录。</p><h3>当前公开版本</h3>${display(ch.content)}<h3>待更新版本</h3>${display(updated.content)}<p class="cg-error" role="alert" id="cg-publish-error"></p></div>`,button('确认更新本集','confirm-revision',w.id,true),true);
 }
 async function commitRevision(){
  const pending=revisionPreview;if(!pending)throw Error('请重新预览修改版本。');await refresh();const current=records.find(w=>w.id===pending.work.id),old=current&&chapters(current).find(ch=>ch.id===pending.chapterId);
  if(!old||JSON.stringify(old)!==pending.based)throw Error('公开版本已经变化，请重新预览。');
  const updated=pending.work.chapters.find(ch=>ch.id===pending.chapterId),next={...current,chapters:chapters(current).map(ch=>ch.id===updated.id?updated:ch),updatedAt:updated.updatedAt};
  await write('works',next);records=records.map(w=>w.id===next.id?next:w);revisionPreview=null;S.close();S.route(chapterURL(next,updated));S.toast('本集成稿已更新，旧版本和读者权限保留');
 }
 function settings(w){draft={settingsId:w.id,visibility:w.visibility,supportEnabled:w.supportEnabled!==false,status:w.status||'连载中'};S.modal('修改展示设置',`<div class="cg-form"><label>展示范围<select data-cg-publish="visibility"><option value="private" ${w.visibility==='private'?'selected':''}>仅自己可见</option><option value="square" ${w.visibility==='square'?'selected':''}>作品广场（本机演示）</option></select></label><label class="cg-check"><input type="checkbox" data-cg-publish="supportEnabled" ${draft.supportEnabled?'checked':''} ${w.demoOnly?'disabled':''}>开启读者支持</label>${w.demoOnly?'<p>静态演示作品不支持付费或打赏。</p>':['story','comic'].includes(w.kind)?`<fieldset><legend>章节积分价格</legend><p>0 为免费；只影响后续购买，已购读者权益和历史订单保留。旧人民币价格需要你确认新的积分价格，不自动换算。</p>${chapters(w).map(ch=>`<label>${E(ch.title)}<input type="number" data-cg-chapter-price="${E(ch.id)}" min="0" max="9999" step="1" placeholder="保留历史价格" value="${(ch.currency||w.currency)==='points'||!ch.price?ch.price:''}">${ch.price&&(ch.currency||w.currency)!=='points'?'<small>旧价格 '+money(ch.price,'legacy')+' · 留空保留原价，暂不开新交易</small>':''}</label>`).join('')}</fieldset>`:''}<p>已发布成稿与阅读订单保留。</p><p class="cg-error" role="alert" id="cg-publish-error"></p></div>`,button('保存展示设置','save-settings',w.id,true));}
 document.addEventListener('input',event=>{const n=event.target;if(n.dataset.cgField)filter[n.dataset.cgField]=n.value;if(n.dataset.cgPublish&&draft)draft[n.dataset.cgPublish]=n.type==='checkbox'?n.checked:n.value;});
 document.addEventListener('change',event=>{
  const n=event.target;if(n.dataset.cgField)filter[n.dataset.cgField]=n.value;if(!n.dataset.cgPublish||!draft)return;
  const field=n.dataset.cgPublish;draft[field]=n.type==='checkbox'?n.checked:n.value;
  if(field==='kind'){resetSource();drawPublish();}else if(field==='key'){resetEpisode();drawPublish();}else if(field==='episode'){draft.chapterTitle=sourceEpisodes(selectedSource()).find(e=>e.id===draft.episode)?.title||'';drawPublish();}else if(field==='seriesId'){const w=find(draft.seriesId);if(w){draft.visibility=w.visibility;draft.supportEnabled=w.supportEnabled!==false;draft.status=w.status||'连载中';}drawPublish();}else if(field==='access')drawPublish();
 });
 document.addEventListener('click',async event=>{
  const n=event.target.closest('[data-cg], [data-cm="publish-work"]');if(!n)return;event.preventDefault();event.stopImmediatePropagation();if(busy)return;
  const action=n.dataset.cg||'publish',w=find(n.dataset.id);
  try{
   if(!loaded&&['publish','favorite','follow','transact','commit','settings','save-settings','support','unlock','orders'].includes(action)){await refresh();if(!loaded)throw Error(failure||'正在读取本机记录，请稍后重试。');}
   if(action==='publish')publish();else if(action==='type'){filter.type=n.dataset.id;S.render();}else if(action==='tab'){filter.tab=n.dataset.id;S.render();}else if(action==='search')S.render();else if(action==='reset'){filter={type:'all',tab:'featured',genre:'all',query:''};S.render();}else if(action==='reload')await refresh();else if(action==='settings')settings(w);else if(action==='chapter'){const ch=chapters(w).find(i=>i.id===n.dataset.chapter);if(ch)S.route(chapterURL(w,ch));}else if(action==='support'||action==='unlock')openTransaction(w,action);else if(action==='orders')orders();
   else{
    busy=true;n.disabled=true;
    if(action==='favorite'){const next=favorites.includes(w.id)?favorites.filter(id=>id!==w.id):[...favorites,w.id];await write('preferences',next,'favorites');favorites=next;S.render();}
    else if(action==='follow'){const next={...reader,following:reader.following.includes(w.id)?reader.following.filter(id=>id!==w.id):[...reader.following,w.id]};await write('preferences',next,'reader-v1');reader=next;S.render();}
    else if(action==='transact')await transact();else if(action==='commit')await commit();else if(action==='confirm-revision')await commitRevision();
    else if(action==='save-settings'){if(!owned(w))throw Error('只能管理自己的作品。');const prices=new Map([...document.querySelectorAll('[data-cg-chapter-price]')].filter(n=>n.value!=='').map(n=>{const price=Number(n.value);if(!Number.isSafeInteger(price)||price<0||price>9999)throw Error('章节价格需为 0–9999 的整数积分。');return [n.dataset.cgChapterPrice,price];}));const next={...w,visibility:draft.visibility,status:draft.status||w.status,supportEnabled:w.demoOnly?false:draft.supportEnabled,...(prices.size?{chapters:chapters(w).map(ch=>prices.has(ch.id)?{...ch,price:prices.get(ch.id),currency:'points'}:ch)}:{}),permissions:{},shared:{}};await write('works',next);records=records.map(r=>r.id===next.id?next:r);S.close();S.render();}
   }
  }catch(error){const target=document.getElementById('cg-publish-error');if(target)target.textContent=error.message;else S.toast(error.message);}finally{busy=false;if(n.isConnected)n.disabled=false;}
 },true);
 C.pages.community=ctx=>{if(!loaded&&!loading&&!failure)void refresh();if(ctx.params.get('view')==='earnings'){history.replaceState(null,'','#/app/creator?tab=income');return earnings();}const id=ctx.parts[2];return id?(find(id)?detail(find(id)):loaded?S.empty('作品不存在','可以继续浏览其他作品。','回到作品广场','/app/community'):'<p role="status">正在读取作品…</p>'):listView();};
 function revisionHistory(id,chapterId){const w=records.find(w=>w.id===id),ch=w&&chapters(w).find(ch=>ch.id===chapterId);if(!owned(w)||!ch)throw Error('修订记录不可用。');S.modal('本集修订记录','<div class="cg-form">'+(ch.revisions||[]).map((r,i)=>'<details><summary>旧版本 '+(ch.revisions.length-i)+' · '+E(r.updatedAt||r.createdAt)+'</summary>'+renderContent(r.content)+'</details>').join('')+'</div>','',true);}
 window.CommunityStudio={all,refresh,history:()=>reader.orders,prepare,examples,write,previewRevision,revisionHistory,publish,status:()=>({loaded,loading,failure}),mine:()=>all().filter(owned),income:()=>reader.orders.filter(order=>records.some(work=>work.id===order.workId))};
 if(onCommunity())S.render();
})();
